from functools import wraps

def trace(original):
    @wraps(original)
    def wrapped(*args, **kwargs):
        return original(*args, **kwargs)
    return wrapped

@trace
def total(count):
    """두 배 수량을 반환합니다."""
    return count * 2

print(total.__name__)
print(total.__doc__)
print(total(3))
